const $=(s,p=document)=>p.querySelector(s),$$=(s,p=document)=>[...p.querySelectorAll(s)];
const dashboard=$('.dashboard'),overlay=$('.overlay'),toast=$('.toast'),demo=$('#demo'),prompt=$('#prompt'),result=$('#demo-result'),authModal=$('.auth-modal'),authCard=$('.auth-card'),authForm=$('#auth-form');let activeTool='post',registerMode=false,currentUser=null,activeProject=null;
const escapeHtml=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const toolNames={post:'Пост-студия',plan:'Контент-план',rewrite:'Редактор тона',chat:'AI-ассистент'};
function showToast(message){toast.textContent=message;toast.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('show'),3200)}
async function api(path,options={}){const response=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})},...options}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Не удалось выполнить запрос.');return data}
function setUser(user){currentUser=user;$('.open-dashboard').textContent=user?(user.name||'Кабинет'):'Войти';if(!user)return;$('.dash-head h2').textContent=`Привет, ${user.name}`;$('.dash-credit b').innerHTML=`${user.credits} <small>Nova Actions</small>`;$('.dash-credit p').textContent=user.plan?`Тариф «${user.plan.name}» · до ${new Date(user.plan.ends_at).toLocaleDateString('ru-RU')}`:'Тариф пока не выбран';$('.dash-credit > div i').style.width=`${Math.min(100,Math.max(3,user.credits*10))}%`;$('.dash-tab[data-panel="admin"]').style.display=user.role==='admin'?'':'none'}
function setActiveProject(project){activeProject=project;$('#active-project-label').textContent=project?`Проект: ${project.name}`:'Сначала выберите проект'}
function openAuth(){authModal.classList.add('open');authModal.setAttribute('aria-hidden','false');$('.auth-error').textContent='';$('#auth-form input[name="email"]').focus()}function closeAuth(){authModal.classList.remove('open');authModal.setAttribute('aria-hidden','true')}function setAuthMode(register){registerMode=register;authCard.classList.toggle('register',register);$('#auth-title').textContent=register?'Создать аккаунт':'Войти в пространство';$('.auth-switch').textContent=register?'Уже есть аккаунт? Войти':'Нет аккаунта? Зарегистрироваться';$('.terms input').required=register;$('.auth-card input[name="password"]').autocomplete=register?'new-password':'current-password'}
function openDashboard(panel='projects'){if(!currentUser)return openAuth();dashboard.classList.add('open');dashboard.setAttribute('aria-hidden','false');overlay.classList.add('show');$$('.dash-tab').forEach(b=>b.classList.toggle('active',b.dataset.panel===panel));$$('.dash-panel').forEach(b=>b.classList.toggle('active',b.id===panel));if(panel==='projects')loadProjects();if(panel==='workspace')loadWorkspace();if(panel==='library')loadMaterials();if(panel==='admin')loadAdmin()}function closeDashboard(){dashboard.classList.remove('open');dashboard.setAttribute('aria-hidden','true');overlay.classList.remove('show')}
function setTool(tool){activeTool=tool;$$('.generator-tabs button').forEach(b=>b.classList.toggle('active',b.dataset.demoTool===tool));const labels={post:['О чём будет пост?','Например: пост для кофейни о первом холодном утре октября'],plan:['Ниша, продукт или задача плана','Например: контент-план для студии йоги на 7 дней'],rewrite:['Текст для улучшения','Вставьте черновик — сделаем его яснее и ближе к аудитории']};$('.generator label[for="prompt"]').textContent=labels[tool][0];prompt.placeholder=labels[tool][1]}
function openDemo(tool='post'){if(!['post','plan','rewrite'].includes(tool)){showToast('Этот сценарий доступен в AI-чате проекта.');return}if(!currentUser)return openAuth();if(!activeProject){showToast('Сначала создайте или выберите проект.');return openDashboard('projects')}demo.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>{setTool(tool);prompt.focus()},450)}
async function loadProjects(){const list=$('.project-list');list.innerHTML='<p class="auth-copy">Загружаем проекты…</p>';try{const{projects}=await api('/api/projects');list.innerHTML=projects.length?projects.map(project=>`<button class="project-card ${activeProject?.id===project.id?'selected':''}" data-id="${project.id}"><b>${escapeHtml(project.name)}</b><small>${escapeHtml(project.description||'Контекст ещё не заполнен')}</small><em>${project.packs_count} паков</em></button>`).join(''):'<p class="auth-copy">Создайте первый проект: он станет отдельным рабочим контекстом.</p>';$$('.project-card',list).forEach(button=>button.addEventListener('click',()=>{const project=projects.find(item=>item.id===Number(button.dataset.id));setActiveProject(project);openDashboard('workspace')}))}catch(error){list.innerHTML=`<p class="auth-error">${escapeHtml(error.message)}</p>`}}
async function loadWorkspace(){const panel=$('.workspace-project');if(!activeProject){panel.innerHTML='<div class="dash-empty"><span>✦</span><h3>Выберите проект</h3><p>Контент, паки и память бренда всегда остаются внутри выбранного проекта.</p><button class="button choose-project" type="button">К проектам <span>→</span></button></div>';$('.choose-project',panel).addEventListener('click',()=>openDashboard('projects'));return}panel.innerHTML='<p class="auth-copy">Собираем рабочее пространство…</p>';try{const[{project,packs},{packs:catalog}]=await Promise.all([api(`/api/projects/${activeProject.id}`),api('/api/packs')]);setActiveProject(project);const attached=packs.map(pack=>`<article class="pack-card"><h4>${escapeHtml(pack.title)}</h4><p>${escapeHtml(pack.description)}</p><div class="pack-steps">${pack.steps.map((step,index)=>`<div class="pack-step"><span>${index+1}. ${escapeHtml(step.title)} · ${step.cost} Action${step.cost>1?'s':''}</span><button data-tool="${step.tool}" data-title="${escapeHtml(step.title)}">Открыть</button></div>`).join('')}</div></article>`).join('');const available=catalog.map(pack=>`<button class="attach-pack" data-id="${pack.id}"><b>${escapeHtml(pack.title)}</b><small>${escapeHtml(pack.description)} · от ${Math.min(...pack.steps.map(s=>s.cost))} Action</small></button>`).join('');panel.innerHTML=`<div class="workspace-title"><div><h3>${escapeHtml(project.name)}</h3><p>${escapeHtml(project.description||'Рабочий контекст проекта')}</p></div><button class="outline-button change-project">Сменить</button></div><div class="pack-card"><h4>Память проекта</h4><p>${escapeHtml(project.brand_context||'Добавьте аудиторию, факты и продукты при создании следующего проекта.')}</p></div><h4 class="workspace-heading">Подключённые паки</h4>${attached||'<p class="auth-copy">Паков ещё нет — выберите готовый или соберите свой.</p>'}<h4 class="workspace-heading">Готовые паки</h4><div class="pack-catalog">${available}</div><form class="custom-pack-form"><b>Собрать свой пак</b><input name="title" maxlength="80" placeholder="Название: например, мини-запуск" required><textarea name="description" maxlength="280" placeholder="Что должен сделать этот пак"></textarea><div class="custom-step-row"><input name="step1" maxlength="80" placeholder="Шаг 1: например, идея поста" required><select name="tool1"><option value="post">Пост · 1</option><option value="plan">План · 3</option><option value="rewrite">Тон · 1</option><option value="chat">Чат · 1</option></select></div><div class="custom-step-row"><input name="step2" maxlength="80" placeholder="Шаг 2 (необязательно)"><select name="tool2"><option value="post">Пост · 1</option><option value="plan">План · 3</option><option value="rewrite">Тон · 1</option><option value="chat">Чат · 1</option></select></div><div class="custom-step-row"><input name="step3" maxlength="80" placeholder="Шаг 3 (необязательно)"><select name="tool3"><option value="post">Пост · 1</option><option value="plan">План · 3</option><option value="rewrite">Тон · 1</option><option value="chat">Чат · 1</option></select></div><button class="button" type="submit">Добавить свой пак <span>→</span></button></form>`;$$('.pack-step button',panel).forEach(button=>button.addEventListener('click',()=>{closeDashboard();setTool(button.dataset.tool);prompt.value=`${button.dataset.title} для проекта «${activeProject.name}»: `;$('#prompt-count').textContent=`${prompt.value.length} / 280`;openDemo(button.dataset.tool)}));$$('.attach-pack',panel).forEach(button=>button.addEventListener('click',async()=>{try{await api('/api/project-packs',{method:'POST',body:JSON.stringify({project_id:activeProject.id,pack_id:Number(button.dataset.id)})});showToast('Пак подключён к проекту.');loadWorkspace()}catch(error){showToast(error.message)}}));$('.change-project',panel).addEventListener('click',()=>openDashboard('projects'));$('.custom-pack-form',panel).addEventListener('submit',async event=>{event.preventDefault();const form=new FormData(event.currentTarget),steps=[1,2,3].map(index=>({title:form.get(`step${index}`),tool:form.get(`tool${index}`)})).filter(step=>step.title.trim());try{await api('/api/project-packs/custom',{method:'POST',body:JSON.stringify({project_id:activeProject.id,title:form.get('title'),description:form.get('description'),steps})});showToast('Свой пак добавлен в проект.');loadWorkspace()}catch(error){showToast(error.message)}})}catch(error){panel.innerHTML=`<p class="auth-error">${escapeHtml(error.message)}</p>`}}
async function loadMaterials(){const panel=$('#library');panel.innerHTML='<p class="auth-copy">Загружаем материалы…</p>';try{const{materials}=await api('/api/materials');panel.innerHTML=materials.length?materials.map(item=>`<article class="library-item"><span>${item.tool==='plan'?'◫':item.tool==='rewrite'?'⌁':'✦'}</span><div><b>${toolNames[item.tool]}</b><small>${new Date(item.created_at).toLocaleString('ru-RU')}</small></div><button class="outline-button material-open">Открыть</button><template>${escapeHtml(item.output_text||'')}</template></article>`).join(''):'<p class="auth-copy">Материалов пока нет.</p>';$$('.material-open',panel).forEach(button=>button.addEventListener('click',()=>{$('.chat-result').textContent=$('template',button.parentElement).content.textContent;openDashboard('workspace')}))}catch(error){panel.innerHTML=`<p class="auth-error">${escapeHtml(error.message)}</p>`}}
async function loadAdmin(){const panel=$('#admin');try{const{overview}=await api('/api/admin/overview');panel.innerHTML=`<div class="admin-warning">Реальная админ‑зона: ключи AI не отображаются и не передаются пользователям.</div>${[['Пользователи',overview.users],['Успешные генерации',overview.generations],['Ошибки AI',overview.errors],['Открытая поддержка',overview.tickets]].map(([n,v])=>`<div class="admin-stat"><span>${n}</span><b>${v}</b></div>`).join('')}`}catch(error){panel.innerHTML=`<p class="auth-error">${escapeHtml(error.message)}</p>`}}
$$('.open-dashboard').forEach(button=>button.addEventListener('click',()=>openDashboard()));$('.close-dashboard').addEventListener('click',closeDashboard);overlay.addEventListener('click',closeDashboard);$('.close-auth').addEventListener('click',closeAuth);$('.auth-switch').addEventListener('click',()=>setAuthMode(!registerMode));authModal.addEventListener('click',event=>{if(event.target===authModal)closeAuth()});$$('.dash-tab').forEach(button=>button.addEventListener('click',()=>openDashboard(button.dataset.panel)));$('.new-project').addEventListener('click',()=>$('.project-form').classList.toggle('open'));$('.project-form').addEventListener('submit',async event=>{event.preventDefault();const form=new FormData(event.currentTarget);try{const data=await api('/api/projects',{method:'POST',body:JSON.stringify(Object.fromEntries(form))});setActiveProject(data.project);event.currentTarget.reset();event.currentTarget.classList.remove('open');showToast('Проект создан. Выберите готовый пак или соберите свой.');openDashboard('workspace')}catch(error){showToast(error.message)}});$$('.scroll-to-demo').forEach(button=>button.addEventListener('click',()=>openDemo()));$$('.tool-card').forEach(card=>card.addEventListener('click',()=>openDemo(card.dataset.tool)));$$('.generator-tabs button').forEach(button=>button.addEventListener('click',()=>setTool(button.dataset.demoTool)));prompt.addEventListener('input',()=>$('#prompt-count').textContent=`${prompt.value.length} / 280`);
authForm.addEventListener('submit',async event=>{event.preventDefault();const form=new FormData(authForm),payload={email:form.get('email'),password:form.get('password')};if(registerMode){payload.name=form.get('name');payload.terms=form.get('terms')==='on'}$('.auth-error').textContent='';try{const data=await api(registerMode?'/api/auth/register':'/api/auth/login',{method:'POST',body:JSON.stringify(payload)});setUser(data.user);closeAuth();showToast(registerMode?'Аккаунт создан: вам начислен стартовый лимит.':'С возвращением!');openDashboard('projects')}catch(error){$('.auth-error').textContent=error.message}});
$('.generate').addEventListener('click',async()=>{if(!currentUser)return openAuth();if(!activeProject){showToast('Сначала выберите проект.');return openDashboard('projects')}if(!prompt.value.trim())return showToast('Сначала опишите задачу.');const button=$('.generate'),tier=$('#model-tier').value;button.disabled=true;button.textContent='Собираем…';try{const data=await api('/api/generate',{method:'POST',body:JSON.stringify({project_id:activeProject.id,tool:activeTool,model_tier:tier,input:{topic:prompt.value,platform:$('#platform').value,tone:$('#tone').value}})});result.classList.remove('empty');result.innerHTML='<div class="result-label"></div><p class="result-text"></p><p class="auth-copy"></p>';$('.result-label',result).textContent=`${toolNames[activeTool]} · списано ${data.generation.cost} Action`;$('.result-text',result).textContent=data.generation.output;$('.auth-copy',result).textContent=data.generation.notice;currentUser.credits=data.generation.credits;setUser(currentUser);showToast('Материал готов и сохранён в проекте.')}catch(error){showToast(error.message)}finally{button.disabled=false;button.innerHTML='Собрать материал <span>↑</span>'}});
$('.chat-send').addEventListener('click',async()=>{if(!currentUser)return openAuth();if(!activeProject){showToast('Сначала выберите проект.');return openDashboard('projects')}const message=$('#chat-message').value.trim();if(!message)return;const button=$('.chat-send');button.disabled=true;try{const data=await api('/api/generate',{method:'POST',body:JSON.stringify({project_id:activeProject.id,tool:'chat',model_tier:$('#chat-model-tier').value,input:{message}})});$('.chat-result').textContent=data.generation.output;currentUser.credits=data.generation.credits;setUser(currentUser)}catch(error){$('.chat-result').textContent=error.message}finally{button.disabled=false}});
$$('.select-plan').forEach(button=>button.addEventListener('click',()=>showToast(`Пакет «${button.dataset.plan}» отмечен. Оплата пока не подключена.`)));const mobileMenu=$('.mobile-menu');mobileMenu.addEventListener('click',()=>{const open=$('.nav').classList.toggle('open');mobileMenu.setAttribute('aria-expanded',String(open))});$$('.nav a').forEach(link=>link.addEventListener('click',()=>$('.nav').classList.remove('open')));const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.12});$$('.reveal').forEach(element=>observer.observe(element));api('/api/me').then(data=>setUser(data.user)).catch(()=>setUser(null));
